1	<script setup>
2	import { ref, computed, onMounted } from 'vue'
3	import { useRoute, useRouter } from 'vue-router'
4	import { useToast } from 'primevue/usetoast'
5	import { useTickerCurrency, usePercent, gainLossClass } from '@/composables/useFormat'
6	import api from '@/composables/useApi'
7	import Button from 'primevue/button'
8	import Tag from 'primevue/tag'
9	import AddTransactionModal from '@/components/ui/AddTransactionModal.vue'
10	
11	const route = useRoute()
12	const router = useRouter()
13	const toast = useToast()
14	
15	const ticker = route.params.ticker.toUpperCase()
16	const transactions = ref([])
17	const currentPrice = ref(null)
18	const loading = ref(false)
19	const showModal = ref(false)
20	
21	onMounted(async () => {
22	  await fetchLots()
23	  fetchQuote()
24	})
25	
26	async function fetchLots() {
27	  loading.value = true
28	  try {
29	    const data = await api.get(`/portfolio/transactions?ticker=${ticker}&limit=500`)
30	    transactions.value = data.transactions.sort((a, b) => new Date(a.date) - new Date(b.date))
31	  } catch (err) {
32	    toast.add({ severity: 'error', summary: 'Failed to load', detail: err.message, life: 3000 })
33	  } finally {
34	    loading.value = false
35	  }
36	}
37	
38	async function fetchQuote() {
39	  try {
40	    const q = await api.get(`/stocks/quote/${ticker}`)
41	    currentPrice.value = q.price
42	  } catch {}
43	}
44	
45	// Compute running weighted average after each transaction
46	const lots = computed(() => {
47	  let shares = 0
48	  let totalCost = 0
49	  return transactions.value.map((tx) => {
50	    if (tx.type === 'buy') {
51	      totalCost += tx.shares * tx.price
52	      shares += tx.shares
53	    } else {
54	      // on sell, reduce cost basis proportionally
55	      totalCost -= (totalCost / shares) * tx.shares
56	      shares -= tx.shares
57	    }
58	    const avgCost = shares > 0 ? totalCost / shares : 0
59	    return { ...tx, runningShares: shares, runningAvg: avgCost }
60	  })
61	})
62	
63	const summary = computed(() => {
64	  if (!lots.value.length) return null
65	  const last = lots.value[lots.value.length - 1]
66	  const shares = last.runningShares
67	  const avgCost = last.runningAvg
68	  const totalCost = shares * avgCost
69	  const currentValue = currentPrice.value != null ? shares * currentPrice.value : null
70	  const pnl = currentValue != null ? currentValue - totalCost : null
71	  // % gain = (current - avg) / avg  — this is your 50% example
72	  const pnlPercent = avgCost > 0 && currentPrice.value != null
73	    ? ((currentPrice.value - avgCost) / avgCost) * 100
74	    : null
75	  return { shares, avgCost, totalCost, currentValue, pnl, pnlPercent }
76	})
77	
78	function formatDate(d) {
79	  return new Date(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
80	}
81	</script>
82	
83	<template>
84	  <div class="position-detail">
85	    <header class="page-header">
86	      <Button icon="pi pi-arrow-left" text rounded @click="router.back()" />
87	      <div class="header-info">
88	        <h1>{{ ticker }}</h1>
89	        <span class="text-muted">Transaction Lots</span>
90	      </div>
91	      <Button icon="pi pi-plus" rounded text @click="showModal = true" />
92	    </header>
93	
94	    <!-- P&L Summary -->
95	    <div v-if="summary" class="pnl-card" :class="gainLossClass(summary.pnl)">
96	      <div class="pnl-main">
97	        <span class="pnl-label">Overall P&L</span>
98	        <span class="pnl-value" :class="gainLossClass(summary.pnl)">
99	          {{ summary.pnl != null ? (summary.pnl >= 0 ? '+' : '') + useTickerCurrency(summary.pnl, ticker) : '—' }}
100	        </span>
101	      </div>
102	      <div class="pnl-pct" :class="gainLossClass(summary.pnlPercent)">
103	        {{ summary.pnlPercent != null ? (summary.pnlPercent >= 0 ? '+' : '') + summary.pnlPercent.toFixed(2) + '%' : '—' }}
104	      </div>
105	      <div class="pnl-formula text-muted">
106	        Avg {{ useTickerCurrency(summary.avgCost, ticker) }} → Current {{ currentPrice != null ? useTickerCurrency(currentPrice, ticker) : '…' }}
107	      </div>
108	    </div>
109	
110	    <!-- Stats row -->
111	    <div v-if="summary" class="stats-row">
112	      <div class="stat-item">
113	        <span class="text-muted">Shares</span>
114	        <span>{{ summary.shares.toFixed(4).replace(/\.?0+$/, '') }}</span>
115	      </div>
116	      <div class="stat-item">
117	        <span class="text-muted">Avg Cost</span>
118	        <span>{{ useTickerCurrency(summary.avgCost, ticker) }}</span>
119	      </div>
120	      <div class="stat-item">
121	        <span class="text-muted">Total Cost</span>
122	        <span>{{ useTickerCurrency(summary.totalCost, ticker) }}</span>
123	      </div>
124	      <div class="stat-item">
125	        <span class="text-muted">Current Value</span>
126	        <span>{{ summary.currentValue != null ? useTickerCurrency(summary.currentValue, ticker) : '…' }}</span>
127	      </div>
128	    </div>
129	
130	    <div v-if="loading" class="text-muted loading">Loading...</div>
131	
132	    <div v-else-if="!lots.length" class="empty">
133	      <i class="pi pi-list" />
134	      <p class="text-muted">No transactions yet</p>
135	      <Button label="Add Transaction" @click="showModal = true" />
136	    </div>
137	
138	    <div v-else class="lots-list">
139	      <h2 class="section-title">Lots</h2>
140	      <div v-for="lot in lots" :key="lot._id" class="lot-row">
141	        <div class="lot-left">
142	          <div class="lot-top">
143	            <Tag :value="lot.type.toUpperCase()" :severity="lot.type === 'buy' ? 'success' : 'danger'" class="lot-tag" />
144	            <span class="lot-date text-muted">{{ formatDate(lot.date) }}</span>
145	          </div>
146	          <div class="lot-detail">
147	            {{ lot.shares }} shares @ {{ useTickerCurrency(lot.price, ticker) }}
148	          </div>
149	          <div v-if="lot.feeAmount" class="lot-fee loss">
150	            {{ lot.type === 'buy' ? 'Buy' : 'Sell' }} fee: {{ useTickerCurrency(lot.feeAmount, ticker) }}
151	            <span v-if="lot.feeProfile?.name"> · {{ lot.feeProfile.name }}</span>
152	          </div>
153	          <div v-if="lot.taxAmount" class="lot-fee loss">
154	            Tax ({{ lot.feeProfile?.capitalGainsTax }}%): {{ useTickerCurrency(lot.taxAmount, ticker) }}
155	          </div>
156	          <div v-if="lot.type === 'sell' && lot.netProceeds != null" class="lot-net gain">
157	            Net proceeds: {{ useTickerCurrency(lot.netProceeds, ticker) }}
158	          </div>
159	          <div v-if="lot.notes" class="lot-notes text-muted">{{ lot.notes }}</div>
160	        </div>
161	        <div class="lot-right">
162	          <span class="lot-total">{{ useTickerCurrency(lot.total, ticker) }}</span>
163	          <span class="lot-avg text-muted">Avg → {{ useTickerCurrency(lot.runningAvg, ticker) }}</span>
164	          <span class="lot-shares text-muted">{{ lot.runningShares.toFixed(2) }} shares held</span>
165	        </div>
166	      </div>
167	    </div>
168	
169	    <AddTransactionModal
170	      v-model:visible="showModal"
171	      :default-ticker="ticker"
172	      @hide="fetchLots"
173	    />
174	  </div>
175	</template>
176	
177	<style scoped>
178	.position-detail { padding: 0.5rem 1rem 2rem; }
179	.page-header { display: flex; align-items: center; gap: 0.5rem; margin-bottom: 1.25rem; }
180	.header-info { flex: 1; }
181	.header-info h1 { font-size: 1.3rem; font-weight: 700; line-height: 1; }
182	.header-info span { font-size: 0.82rem; }
183	
184	.pnl-card {
185	  background: var(--bg-card);
186	  border: 1px solid var(--border);
187	  border-radius: 16px;
188	  padding: 1.25rem;
189	  margin-bottom: 0.75rem;
190	  text-align: center;
191	}
192	.pnl-card.gain { border-color: rgba(34,197,94,0.3); }
193	.pnl-card.loss { border-color: rgba(239,68,68,0.3); }
194	.pnl-main { display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; }
195	.pnl-label { font-size: 0.82rem; color: var(--text-secondary); }
196	.pnl-value { font-size: 1.3rem; font-weight: 700; }
197	.pnl-pct { font-size: 2rem; font-weight: 700; margin: 0.25rem 0; }
198	.pnl-formula { font-size: 0.78rem; margin-top: 6px; }
199	
200	.stats-row {
201	  display: grid;
202	  grid-template-columns: 1fr 1fr;
203	  gap: 0;
204	  background: var(--bg-card);
205	  border: 1px solid var(--border);
206	  border-radius: 12px;
207	  overflow: hidden;
208	  margin-bottom: 1.5rem;
209	}
210	.stat-item {
211	  display: flex;
212	  justify-content: space-between;
213	  align-items: center;
214	  padding: 0.7rem 1rem;
215	  border-bottom: 1px solid var(--border);
216	  font-size: 0.85rem;
217	}
218	.stat-item:nth-last-child(-n+2) { border-bottom: none; }
219	.stat-item .text-muted { font-size: 0.78rem; }
220	
221	.loading { padding: 1rem 0; }
222	.empty { display: flex; flex-direction: column; align-items: center; gap: 1rem; padding: 3rem 1rem; }
223	.empty i { font-size: 3rem; color: var(--text-secondary); }
224	
225	.section-title { font-size: 0.85rem; font-weight: 600; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 0.5rem; }
226	.lots-list { display: flex; flex-direction: column; }
227	.lot-row { display: flex; justify-content: space-between; align-items: flex-start; padding: 0.85rem 0; border-bottom: 1px solid var(--border); gap: 0.5rem; }
228	.lot-left { flex: 1; display: flex; flex-direction: column; gap: 3px; }
229	.lot-top { display: flex; align-items: center; gap: 0.5rem; margin-bottom: 2px; }
230	.lot-tag { font-size: 0.7rem; }
231	.lot-date { font-size: 0.78rem; }
232	.lot-detail { font-size: 0.88rem; }
233	.lot-fee { font-size: 0.75rem; }
234	.lot-net { font-size: 0.75rem; }
235	.lot-notes { font-size: 0.78rem; font-style: italic; }
236	.lot-right { display: flex; flex-direction: column; align-items: flex-end; gap: 2px; }
237	.lot-total { font-weight: 600; font-size: 0.95rem; }
238	.lot-avg { font-size: 0.75rem; }
239	.lot-shares { font-size: 0.75rem; }
240	</style>
